// Writes the drum banks bundled with zvid to public/drum-banks/, one folder
// per entry of DRUM_BANKS in src/fx/effects/drum-rack/banks.ts with one
// `.wav` file per pad, plus the CREDITS.md that lists them. Every sound is
// synthesized here, modeled on how its machine makes it (the TR-808's
// bridged-T drums and six-square-wave metal, the TR-909's swept kick and
// noise, the CR-78's damped pings, a game console's square, triangle and
// noise channels), so every file is generated by zvid and carries no
// third-party license. The output is committed; the unit tests fail when a
// committed file no longer matches its voice.
//
//   node scripts/gen-drum-banks.mjs          regenerate the banks
//   node scripts/gen-drum-banks.mjs --check  exit 1 if a file is stale

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { DRUM_BANKS } from "../src/fx/effects/drum-rack/banks.ts";

const APP_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
export const BANKS_DIR = join(APP_DIR, "public", "drum-banks");
export const CREDITS_PATH = join(BANKS_DIR, "CREDITS.md");

export const SAMPLE_RATE = 44_100;
// Every sound is normalized to this peak, 1 dB under full scale.
export const PEAK = 0.89;
// A sound ends once it stays this far under its peak (-60 dB).
const TAIL_FLOOR = 0.001;
// The fade-out over a sound's end: its last tenth, and at least this long,
// so a tail cut before it reaches the floor ends smoothly.
const FADE_OUT_SECONDS = 0.005;

const TWO_PI = 2 * Math.PI;

// A seeded random generator (mulberry32) returning numbers in [-1, 1).
function noiseSource(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = Math.imul(state ^ (state >>> 15), 1 | state);
    value ^= value + Math.imul(value ^ (value >>> 7), 61 | value);
    return (((value ^ (value >>> 14)) >>> 0) / 4294967296) * 2 - 1;
  };
}

const frames = (seconds) => Math.round(seconds * SAMPLE_RATE);

// `seconds` of `fn(t)` at the sample rate.
function render(seconds, fn) {
  const out = new Float32Array(frames(seconds));
  for (let index = 0; index < out.length; index++) {
    out[index] = fn(index / SAMPLE_RATE, index);
  }
  return out;
}

function noise(seconds, seed) {
  const next = noiseSource(seed);
  return render(seconds, () => next());
}

// An oscillator whose frequency glides from `from` to `to` with time
// constant `glide`; `shape` maps its phase, in cycles, to a sample.
function sweep(seconds, from, to, glide, shape = sine) {
  let phase = 0;
  return render(seconds, (t) => {
    const frequency = glide > 0 ? to + (from - to) * Math.exp(-t / glide) : to;
    const sample = shape(phase);
    phase += frequency / SAMPLE_RATE;
    return sample;
  });
}

const sine = (phase) => Math.sin(TWO_PI * phase);
const square = (phase) => (phase % 1 < 0.5 ? 1 : -1);
const pulse = (duty) => (phase) => (phase % 1 < duty ? 1 : -1);
const triangle = (phase) => 1 - 4 * Math.abs((phase % 1) - 0.5);

const tone = (seconds, frequency, shape = sine) =>
  sweep(seconds, frequency, frequency, 0, shape);

// The six detuned square waves the TR-808 builds its hats, cymbal and
// cowbell from (scaled by `scale`).
const METAL_808 = [205.3, 304.4, 369.6, 522.7, 540, 800];
function metal(seconds, frequencies, scale = 1) {
  const voices = frequencies.map((frequency) =>
    tone(seconds, frequency * scale, square),
  );
  return render(
    seconds,
    (_, index) =>
      voices.reduce((sum, voice) => sum + voice[index], 0) / voices.length,
  );
}

// An RBJ biquad over `input`.
function biquad(input, type, frequency, q = Math.SQRT1_2) {
  const w = (TWO_PI * frequency) / SAMPLE_RATE;
  const alpha = Math.sin(w) / (2 * q);
  const cos = Math.cos(w);
  let b0;
  let b1;
  let b2;
  if (type === "lowpass") {
    b0 = (1 - cos) / 2;
    b1 = 1 - cos;
    b2 = b0;
  } else if (type === "highpass") {
    b0 = (1 + cos) / 2;
    b1 = -(1 + cos);
    b2 = b0;
  } else {
    b0 = alpha;
    b1 = 0;
    b2 = -alpha;
  }
  const a0 = 1 + alpha;
  const a1 = -2 * cos;
  const a2 = 1 - alpha;
  const out = new Float32Array(input.length);
  let x1 = 0;
  let x2 = 0;
  let y1 = 0;
  let y2 = 0;
  for (let index = 0; index < input.length; index++) {
    const x = input[index];
    const y = (b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) / a0;
    out[index] = y;
    x2 = x1;
    x1 = x;
    y2 = y1;
    y1 = y;
  }
  return out;
}

const lowpass = (input, frequency, q) => biquad(input, "lowpass", frequency, q);
const highpass = (input, frequency, q) =>
  biquad(input, "highpass", frequency, q);
const bandpass = (input, frequency, q) =>
  biquad(input, "bandpass", frequency, q);

// `input` times an envelope `fn(t)`.
function shaped(input, fn) {
  return input.map((sample, index) => sample * fn(index / SAMPLE_RATE));
}

// An exponential decay with time constant `decay` after a linear attack.
const decay =
  (time, attack = 0.0005) =>
  (t) =>
    t < attack ? t / attack : Math.exp(-(t - attack) / time);

const decayed = (input, time, attack) => shaped(input, decay(time, attack));

// The sum of `parts`, each `[signal, gain]`, as long as the longest.
function mix(...parts) {
  const length = Math.max(...parts.map(([signal]) => signal.length));
  const out = new Float32Array(length);
  for (const [signal, gain] of parts) {
    for (let index = 0; index < signal.length; index++) {
      out[index] += signal[index] * gain;
    }
  }
  return out;
}

const saturate = (input, drive) =>
  input.map((sample) => Math.tanh(sample * drive));

// A hand clap: a few quick noise bursts, then the room's tail.
function clap(seconds, center, bursts, tail, seed) {
  const source = bandpass(noise(seconds, seed), center, 1.4);
  const last = bursts[bursts.length - 1];
  return shaped(source, (t) => {
    let level = t >= last ? 0.75 * Math.exp(-(t - last) / tail) : 0;
    for (const at of bursts) {
      if (t >= at) {
        level = Math.max(level, Math.exp(-(t - at) / 0.004));
      }
    }
    return level;
  });
}

// A drum that drops from `from` to `to` Hz as it decays.
function drum(seconds, from, to, glide, time, shape = sine) {
  return decayed(sweep(seconds, from, to, glide, shape), time);
}

// A game console's pseudo-random noise channel: a 15-bit shift register
// clocked at `rate`, tapping bit 6 in its short, metallic mode.
function lfsr(seconds, rate, short = false) {
  let register = 1;
  let phase = 0;
  let value = 1;
  return render(seconds, () => {
    phase += rate / SAMPLE_RATE;
    while (phase >= 1) {
      phase -= 1;
      const bit = (register ^ (register >> (short ? 6 : 1))) & 1;
      register = (register >> 1) | (bit << 14);
      value = register & 1 ? 1 : -1;
    }
    return value;
  });
}

// `input` as a 4-bit DAC at a quarter of the sample rate would play it.
function crush(input) {
  let held = 0;
  return input.map((sample, index) => {
    if (index % 4 === 0) {
      held = Math.round(Math.max(-1, Math.min(1, sample)) * 7.5) / 7.5;
    }
    return held;
  });
}

