// `sound` trimmed once it falls for good under the tail floor, faded out
// over its end and normalized to PEAK.
export function finish(sound) {
  let peak = 0;
  for (const sample of sound) {
    peak = Math.max(peak, Math.abs(sample));
  }
  if (!(peak > 0)) {
    throw new Error("Silent drum sound");
  }
  let end = sound.length;
  while (end > 1 && Math.abs(sound[end - 1]) < peak * TAIL_FLOOR) {
    end--;
  }
  const out = new Float32Array(end);
  const fade = Math.min(
    end,
    Math.max(frames(FADE_OUT_SECONDS), Math.round(end / 10)),
  );
  for (let index = 0; index < end; index++) {
    const fromEnd = end - index;
    const gain = fromEnd < fade ? fromEnd / fade : 1;
    out[index] = (sound[index] / peak) * PEAK * gain;
  }
  return out;
}

/** `samples` as a mono 16-bit PCM `.wav` file. */
export function encodeWav(samples, sampleRate = SAMPLE_RATE) {
  const data = samples.length * 2;
  const buffer = Buffer.alloc(44 + data);
  buffer.write("RIFF", 0, "ascii");
  buffer.writeUInt32LE(36 + data, 4);
  buffer.write("WAVE", 8, "ascii");
  buffer.write("fmt ", 12, "ascii");
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(1, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28);
  buffer.writeUInt16LE(2, 32);
  buffer.writeUInt16LE(16, 34);
  buffer.write("data", 36, "ascii");
  buffer.writeUInt32LE(data, 40);
  samples.forEach((sample, index) => {
    const clamped = Math.max(-1, Math.min(1, sample));
    buffer.writeInt16LE(Math.round(clamped * 32767), 44 + index * 2);
  });
  return buffer;
}

export function renderCredits(banks = DRUM_BANKS) {
  const rows = banks.map(
    (entry) =>
      `| \`${entry.slug}/\` | ${entry.name} | \`${entry.id}\` | Synthesized by zvid | zvid | Same as zvid | — |`,
  );
  return `# zvid built-in drum banks: credits

These are the drum banks listed in the Drum Rack effect's bank menu. Keep
this file with them when you redistribute them.

Every sound here is synthesized by zvid: \`app/scripts/gen-drum-banks.mjs\`
models each one on how its drum machine makes it and renders it as a
${SAMPLE_RATE / 1000} kHz, 16-bit mono \`.wav\` file. None is sampled from a
machine or taken from a third-party sample pack, so none carries a
third-party license; they are distributed under zvid's own license. Bank
names describe the machine a bank imitates and are trademarks of their
owners, who do not endorse zvid.

| Folder | Bank | Id | Source | Author | License | License URL |
| --- | --- | --- | --- | --- | --- | --- |
${rows.join("\n")}
`;
}

/** Every file the generator owns, as `[path, contents]`. */
export function renderAll() {
  const files = DRUM_BANKS.flatMap((entry) => {
    const voices = VOICES[entry.id];
    if (!voices) throw new Error(`No voices for drum bank ${entry.id}`);
    return entry.pads.map((pad) => {
      const voice = voices[pad.name];
      if (!voice) throw new Error(`No voice for ${entry.id} ${pad.name}`);
      return [
        join(BANKS_DIR, entry.slug, pad.file),
        encodeWav(finish(voice())),
      ];
    });
  });
  files.push([CREDITS_PATH, Buffer.from(renderCredits())]);
  return files;
}

function readOrEmpty(file) {
  try {
    return readFileSync(file);
  } catch {
    return Buffer.alloc(0);
  }
}

function main() {
  const check = process.argv.includes("--check");
  const stale = [];
  for (const [file, expected] of renderAll()) {
    if (readOrEmpty(file).equals(expected)) continue;
    if (check) {
      stale.push(file);
    } else {
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, expected);
    }
  }
  if (stale.length > 0) {
    console.error(
      `Stale built-in drum banks; run node app/scripts/gen-drum-banks.mjs:\n${stale.join("\n")}`,
    );
    process.exit(1);
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
